SELECT id, plan, end_date, start_date, monthly_fee, LAST_VALUE(start_date) OVER (PARTITION BY plan ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) last_start_date, ROUND(AVG(monthly_fee) OVER (PARTITION BY plan ORDER BY end_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) monthly_fee_moving_avg_3 FROM subscriptions ORDER BY monthly_fee_moving_avg_3 DESC;
